look.customCSS:
/* ───── 云眸入梦 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/220px 260px,radial-gradient(ellipse at 50% 108%,#FFB8DE 0 18%,rgba(246,185,220,.55) 30%,transparent 55%),linear-gradient(180deg,#2B1F55 0%,#4A3285 45%,#8A4FA8 85%,#C46AB0 100%) !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：不做框，往下淡出，底下一道淡粉细线 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,rgba(43,31,85,.9),rgba(43,31,85,0)) !important;border-bottom:none !important;box-shadow:none !important;gap:6px !important;z-index:5 !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:10% !important;right:10% !important;bottom:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,200,230,.8),transparent) !important;pointer-events:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.15em !important}
[data-wk="headdim"]{color:#D8CCEC !important;white-space:nowrap !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#fff !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#fff !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{flex:none !important;width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]),[data-wk="chathead"] + *:not([data-wk="body"]) *{color:#fff !important}

/* 头像：一只石头眼皮的巨眼，照片就是瞳孔，外圈一道彩虹光 */
button[data-wk="avatar"],span[data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:50% !important;box-shadow:0 0 14px 3px rgba(255,200,240,.5) !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important;border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:-42% !important;right:-42% !important;top:-12% !important;bottom:-12% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important;border:none !important;border-radius:0 !important;filter:drop-shadow(0 3px 5px rgba(20,10,50,.45)) !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before{content:none !important}
[data-wk="chathead"] img[data-wk="avatar"]{box-shadow:0 0 0 2.5px #fff,0 0 0 5px rgba(201,138,255,.6) !important}
[data-wk="msg"] [data-wk="row"]{gap:22px !important}
[data-wk="msg"][data-me="0"] [data-wk="row"]{padding-left:12px !important}
[data-wk="msg"][data-me="1"] [data-wk="row"]{padding-right:12px !important}

/* 气泡：一朵云——上下两排圆鼓鼓的边；他的粉白云，我的暗紫雨云。一串第一条里睁着一只彩虹眼 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border:none !important;border-radius:14px !important;letter-spacing:.1em !important;padding:11px 20px !important;margin:16px 16px 12px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;left:-8px !important;right:-8px !important;top:-9px !important;bottom:-8px !important;z-index:-1 !important;border:none !important;transform:none !important;width:auto !important;height:auto !important;pointer-events:none !important;border-radius:24px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FDEAF4 !important;color:#5A3A70 !important;box-shadow:0 0 22px 6px rgba(255,190,225,.5) !important;filter:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{background:radial-gradient(circle,#FDEAF4 10.5px,transparent 13px) 4px 0/31px 26px repeat-x,radial-gradient(circle,#FDEAF4 7.5px,transparent 10px) 15px 5px/23px 20px repeat-x,radial-gradient(circle,#FDEAF4 11.5px,transparent 14px) 26px 1px/43px 28px repeat-x,radial-gradient(circle,#FDEAF4 8.5px,transparent 11px) 9px calc(100% - 2px)/27px 22px repeat-x,radial-gradient(circle,#FDEAF4 10.5px,transparent 13px) 0 100%/37px 26px repeat-x,radial-gradient(circle,#FDEAF4 6.5px,transparent 9px) 12px calc(100% - 5px)/19px 18px repeat-x,radial-gradient(circle,#FDEAF4 8.5px,transparent 11px) 0 3px/22px 21px repeat-y,radial-gradient(circle,#FDEAF4 6.5px,transparent 9px) 4px 12px/18px 17px repeat-y,radial-gradient(circle,#FDEAF4 8.5px,transparent 11px) 100% 6px/22px 23px repeat-y,radial-gradient(circle,#FDEAF4 6.5px,transparent 9px) calc(100% - 4px) 0/18px 15px repeat-y !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#5A5288 !important;color:#fff !important;box-shadow:0 0 20px 5px rgba(150,130,220,.45) !important;filter:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{background:radial-gradient(circle,#5A5288 10.5px,transparent 13px) 4px 0/31px 26px repeat-x,radial-gradient(circle,#5A5288 7.5px,transparent 10px) 15px 5px/23px 20px repeat-x,radial-gradient(circle,#5A5288 11.5px,transparent 14px) 26px 1px/43px 28px repeat-x,radial-gradient(circle,#5A5288 8.5px,transparent 11px) 9px calc(100% - 2px)/27px 22px repeat-x,radial-gradient(circle,#5A5288 10.5px,transparent 13px) 0 100%/37px 26px repeat-x,radial-gradient(circle,#5A5288 6.5px,transparent 9px) 12px calc(100% - 5px)/19px 18px repeat-x,radial-gradient(circle,#5A5288 8.5px,transparent 11px) 0 3px/22px 21px repeat-y,radial-gradient(circle,#5A5288 6.5px,transparent 9px) 4px 12px/18px 17px repeat-y,radial-gradient(circle,#5A5288 8.5px,transparent 11px) 100% 6px/22px 23px repeat-y,radial-gradient(circle,#5A5288 6.5px,transparent 9px) calc(100% - 4px) 0/18px 15px repeat-y !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"]{padding-right:50px !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;right:14px !important;top:50% !important;width:30px !important;height:17px !important;margin-top:-9px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important;left:auto !important;bottom:auto !important;animation:ceBlink 5s ease-in-out infinite !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]{padding-right:20px !important;padding-left:50px !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::after{right:auto !important;left:14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
@keyframes ceBlink{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.1)}}

/* 时间：一行淡紫小字 */
[data-wk="time"] > span{background:transparent !important;border:none !important;box-shadow:none !important;color:#D8CCEC !important;letter-spacing:.3em !important;font-size:11.5px !important}
/* 已送达＝闭着的眼；已读＝睁开的彩虹眼 */
[data-wk="meta"]{color:#D8CCEC !important;font-size:11px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:8px !important}
[data-wk="meta"]::after{content:"" !important;width:20px !important;height:11px !important;flex:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 4px rgba(255,200,240,.8)) !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFE8F4 !important;border:none !important;border-radius:26px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#5A3A70 !important}
[data-wk="name"]{color:#D8CCEC !important}

/* 动描：一缕飘着的薄云，字是粉白斜体，左边一只半睁的眼 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{position:relative !important;display:block !important;background:radial-gradient(ellipse at 50% 50%,rgba(255,220,240,.22),transparent 72%) !important;border:none !important;border-radius:40px !important;box-shadow:none !important;color:#FFE4F2 !important;font-style:italic !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.08em !important;text-shadow:0 0 8px rgba(255,190,225,.5) !important;padding:8px 18px 8px 44px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:24px !important;height:13px !important;margin-top:-7px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:.85 !important}
[data-wk="myactink"]{padding:8px 44px 8px 18px !important;text-align:right !important}
[data-wk="myactink"]::before{left:auto !important;right:12px !important}
[data-wk="narrbar"]{background:rgba(43,31,85,.95) !important;border-top:1px solid rgba(255,200,230,.4) !important}
[data-wk="narrkind"]{border:1px solid rgba(216,204,236,.5) !important;border-radius:999px !important;background:transparent !important;color:#D8CCEC !important}
[data-wk="narrkind"][data-on="1"]{background:#FFE8F4 !important;border-color:#FFE8F4 !important;color:#5A3A70 !important}
/* 系统提示：一行小字，两头各一颗星 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{display:inline-block !important;background:radial-gradient(circle,#fff 1.4px,transparent 2px) left center/8px 8px no-repeat,radial-gradient(circle,#fff 1.4px,transparent 2px) right center/8px 8px no-repeat !important;border:none !important;color:#D8CCEC !important;font-size:11px !important;font-style:normal !important;letter-spacing:.12em !important;padding:0 16px !important}
[data-wk="sysnoteclose"]{color:#D8CCEC !important}

/* 底栏：不做框，往上透出底下那片粉云，上沿一道淡粉线；最右「让他回复」＝粉云里睁着的大眼 */
[data-wk="composer"]{position:relative !important;background:linear-gradient(180deg,rgba(196,106,176,0),rgba(150,80,160,.6)) !important;border-top:none !important;box-shadow:none !important;align-items:center !important;gap:10px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:10% !important;right:10% !important;top:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,200,230,.8),transparent) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:rgba(255,255,255,.14) !important;border:1px solid rgba(255,220,240,.6) !important;border-radius:999px !important;color:#fff !important}
[data-wk="chatinput"]::placeholder{color:#F4DDF0 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:36px !important;min-width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:52px !important;min-width:52px !important;height:44px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 10px rgba(255,200,235,.8)) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:rgba(43,31,85,.96) !important;border-top:1px solid rgba(255,200,230,.4) !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}

/* ───── 云眸入梦 · 第二批：卡片 ───── */
[data-wk="voice"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:linear-gradient(180deg,rgba(255,232,244,.16),rgba(120,90,180,.22)) !important;border:none !important;border-radius:16px !important;box-shadow:inset 0 0 0 1px rgba(255,220,240,.55),0 0 18px rgba(255,180,230,.25) !important;color:#fff !important}
[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#fff !important;border-color:rgba(255,220,240,.4) !important}

/* 转账＝一颗落进云里的星：收下了被一只眼睛接住，退回了星星熄灭 */
[data-wk="transfercard"]{position:relative !important;background:linear-gradient(180deg,rgba(255,232,244,.16),rgba(120,90,180,.22)) !important;border:none !important;border-radius:16px !important;box-shadow:inset 0 0 0 1px rgba(255,220,240,.55),0 0 18px rgba(255,180,230,.25) !important;color:#fff !important;padding-left:78px !important}
[data-wk="transfercard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:56px !important;height:42px !important;margin-top:-24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 6px rgba(255,240,170,.8)) !important}
[data-wk="transfercard"] *{color:#fff !important;border-color:rgba(255,220,240,.4) !important}
[data-wk="transferlabel"]{color:#F6B9DC !important;letter-spacing:.2em !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#FFF3B0 !important;text-shadow:0 0 8px rgba(255,240,170,.6) !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,220,240,.7),transparent) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:rgba(43,31,85,.5) !important}
[data-wk="transferbtn"]{border-radius:999px !important;letter-spacing:.15em !important}
[data-wk="transferbtn"][data-part="take"]{background:#FFE8F4 !important;color:#5A3A70 !important;border:none !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;color:#fff !important;border:1px solid rgba(255,220,240,.7) !important}
[data-wk="transferseal"]{background:transparent !important;border:1px solid #F6B9DC !important;color:#F6B9DC !important;border-radius:50% !important;box-shadow:none !important}
[data-wk="transfercard"][data-status="accepted"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="returned"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:none !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.6 !important}

/* 红包＝一朵睡着的粉云（闭眼打呼）；领完了云睁开眼 */
[data-wk="rpcard"]{position:relative !important;width:220px !important;min-height:80px !important;padding:16px 16px 16px 84px !important;background:linear-gradient(180deg,rgba(255,232,244,.16),rgba(120,90,180,.22)) !important;border:none !important;border-radius:16px !important;box-shadow:inset 0 0 0 1px rgba(255,220,240,.55),0 0 18px rgba(255,180,230,.25) !important;color:#fff !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:10px !important;top:50% !important;width:64px !important;height:46px !important;margin-top:-24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;animation:ceFloat 4s ease-in-out infinite !important}
[data-wk="rpcard"]::after{content:"别吵醒它" !important;position:absolute !important;right:14px !important;bottom:7px !important;font-size:10.5px !important;letter-spacing:.15em !important;color:#F6B9DC !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"] > div:not([data-wk]){padding:0 !important;background:transparent !important}
[data-wk="rpmsg"]{-webkit-line-clamp:2 !important}
[data-wk="rpcard"][data-status="done"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;animation:none !important}
[data-wk="rpcard"][data-status="done"]::after{content:"它醒了" !important}
@keyframes ceFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
/* 拆红包：关着＝一整朵睡着的大云（四周云团、中间一道闭眼），「开」＝一只彩虹眼；拆开＝云散开，里面一片星空，钱是星光写的 */
[data-wk="rpenvelope"]{position:relative !important;overflow:visible !important}
[data-wk="rpenvelope"][data-stage="closed"]{background:radial-gradient(ellipse at 50% 35%,#FFFAFD,#FFE8F4 60%,#F2C6E0) !important;border:none !important;border-radius:40px !important;isolation:isolate !important;box-shadow:0 0 40px 10px rgba(255,190,230,.45) !important}
[data-wk="rpenvelope"][data-stage="closed"]::before{content:"" !important;position:absolute !important;left:-10px !important;right:-10px !important;top:-11px !important;bottom:-10px !important;z-index:-1 !important;border-radius:60px !important;background:radial-gradient(circle,#FFE8F4 11.5px,transparent 14px) 4px 0/33px 28px repeat-x,radial-gradient(circle,#FFE8F4 8.5px,transparent 11px) 15px 5px/25px 22px repeat-x,radial-gradient(circle,#FFE8F4 13.5px,transparent 16px) 26px 1px/47px 32px repeat-x,radial-gradient(circle,#FFE8F4 9.5px,transparent 12px) 9px calc(100% - 2px)/29px 24px repeat-x,radial-gradient(circle,#FFE8F4 11.5px,transparent 14px) 0 100%/39px 28px repeat-x,radial-gradient(circle,#FFE8F4 9.5px,transparent 12px) 0 5px/24px 25px repeat-y,radial-gradient(circle,#FFE8F4 7.5px,transparent 10px) 5px 14px/20px 19px repeat-y,radial-gradient(circle,#FFE8F4 9.5px,transparent 12px) 100% 8px/24px 27px repeat-y,radial-gradient(circle,#FFE8F4 7.5px,transparent 10px) calc(100% - 5px) 0/20px 17px repeat-y !important}
[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rparc"]{display:none !important}
[data-wk="rpenvelope"][data-stage="closed"] *{color:#5A3A70 !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;border-radius:50% !important;box-shadow:0 0 20px 6px rgba(255,200,240,.7) !important;animation:ceGlow 2.4s ease-in-out infinite !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
@keyframes ceGlow{0%,100%{box-shadow:0 0 14px 4px rgba(255,200,240,.55)}50%{box-shadow:0 0 26px 10px rgba(255,200,240,.9)}}
[data-wk="rpenvelope"][data-stage="open"]{background:url("data:image/svg+xml;base64,") 0 0/220px 260px,radial-gradient(ellipse at 50% 115%,#FFB8DE 0 20%,transparent 60%),linear-gradient(180deg,#2B1F55,#4A3285 60%,#8A4FA8) !important;border:none !important;border-radius:28px !important;box-shadow:inset 0 0 0 1px rgba(255,220,240,.5),0 0 40px rgba(255,180,230,.4) !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"]{display:none !important}
[data-wk="rpenvelope"][data-stage="open"] *{color:#fff !important}
[data-wk="rpavatar"]{border-radius:50% !important;box-shadow:0 0 0 3px #FFE8F4,0 0 14px 4px rgba(255,200,240,.7) !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rpamount"] + *::after{content:" · 梦醒了" !important}
[data-wk="rpamount"]{color:#FFF3B0 !important;background:none !important;text-shadow:0 0 12px rgba(255,240,170,.8) !important}
[data-wk="rpclose"]{background:rgba(255,255,255,.15) !important;border:1px solid rgba(255,220,240,.7) !important;color:#fff !important}

/* 照片：透过一只巨眼看出去——相片四角圆，外圈一道彩虹光，上下两片眼皮弧 */
[data-wk="photocard"]{position:relative !important;overflow:visible !important;background:#1A1030 !important;border:none !important;border-radius:50% / 34% !important;padding:16px 12px !important;box-shadow:0 0 0 2px #fff,0 0 0 5px rgba(255,138,216,.6),0 0 0 8px rgba(106,240,192,.35),0 0 24px 8px rgba(255,190,230,.4) !important}
[data-wk="photoface"]{background:linear-gradient(180deg,#4A3285,#8A4FA8) !important;border:none !important;border-radius:40% / 30% !important}
[data-wk="photoface"] *,[data-wk="phototext"]{color:#fff !important}
[data-wk="photocap"],[data-wk="photohint"]{color:#D8CCEC !important}

/* 语音：小云卡，前面一只眨着的眼当播放，波纹是粉色 */
[data-wk="voice"] > *{background:transparent !important;box-shadow:none !important;border:none !important;color:#fff !important}
[data-wk="voice"][data-me]{padding:0 14px 0 44px !important;position:relative !important;border-radius:999px !important}
[data-wk="voice"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:24px !important;height:14px !important;margin-top:-7px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;animation:ceBlink 4s ease-in-out infinite !important}
[data-wk="voice"][data-me="0"]{background:#FFE8F4 !important;box-shadow:0 0 14px rgba(255,190,225,.45) !important}
[data-wk="voice"][data-me="0"] > *{color:#5A3A70 !important}
[data-wk="voice"][data-me="0"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="voice"][data-me="0"] [data-wk="voicewave"] span{background:#5A3A70 !important}
[data-wk="voice"][data-me="1"]{background:#5A5288 !important}
[data-wk="voicewave"] span{background:#F6B9DC !important}

[data-wk="wxcardsky"]{background:linear-gradient(180deg,#4A3285,#8A4FA8) !important}
[data-wk="wxcardsky"] *{color:#fff !important}
[data-wk="wxcardsky"] svg{stroke:#fff !important}
[data-wk="wxcardsay"]{background:rgba(43,31,85,.6) !important;color:#F6B9DC !important;border-top:1px solid rgba(255,220,240,.35) !important}
/* 定位：一颗云做的大头针，针头一只眼 */
[data-wk="geopin"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:none !important;border:none !important;width:22px !important;height:30px !important;border-radius:0 !important;filter:drop-shadow(0 0 6px rgba(255,200,240,.8)) !important}
[data-wk="geopin"] *{opacity:0 !important}
[data-wk="geopinstem"]{background:#F6B9DC !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2px #fff,0 0 10px 3px rgba(255,200,240,.7) !important}

/* 拍一拍、通话结束：一行粉字，前面一只眨眼 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:url("data:image/svg+xml;base64,") left center/18px 10px no-repeat !important;border:none !important;border-radius:0 !important;padding:2px 0 2px 24px !important;color:#F6B9DC !important;letter-spacing:.12em !important;box-shadow:none !important}
[data-wk="note"][data-part="call"] svg{stroke:#F6B9DC !important}
[data-wk="note"][data-part="callsum"]{display:block !important;margin:6px auto 0 !important;max-width:86% !important;background:linear-gradient(180deg,rgba(255,232,244,.16),rgba(120,90,180,.22)) !important;border:none !important;border-radius:16px !important;box-shadow:inset 0 0 0 1px rgba(255,220,240,.55),0 0 18px rgba(255,180,230,.25) !important;color:#fff !important;padding:9px 14px !important}
[data-wk="noteink"]{color:#D8CCEC !important}

/* 线下小结：一页「梦的记录」，标题前一只眼，底下一行「醒来后记下的」 */
[data-part="offlog"]{position:relative !important;padding-top:24px !important;padding-bottom:30px !important}
[data-part="offlog"]::after{content:"— 醒来后记下的" !important;position:absolute !important;right:16px !important;bottom:10px !important;font-size:11px !important;letter-spacing:.15em !important;color:#F6B9DC !important}
[data-wk="offlogtitle"]{display:inline-block !important;margin:0 0 8px !important;padding:0 0 0 30px !important;background:url("data:image/svg+xml;base64,") left center/22px 12px no-repeat !important;color:#fff !important;letter-spacing:.2em !important}
[data-wk="offlogtitle"] *{color:#fff !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#F6B9DC !important}
[data-wk="offlogtranscript"]{border-top:1px solid rgba(255,220,240,.35) !important;color:#D8CCEC !important}

/* 加号面板：一格格小云 */
[data-wk="chattoolicon"]{background:radial-gradient(ellipse at 50% 35%,#FFFAFD,#FFE8F4 70%,#F2C6E0) !important;border:none !important;border-radius:44% 44% 38% 38% !important;box-shadow:0 0 12px rgba(255,190,225,.5) !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#5A3A70 !important;color:#5A3A70 !important}
[data-wk="chattoollabel"]{color:#D8CCEC !important}

/* 引用 */
[data-wk="quotedraft"]{background:rgba(43,31,85,.9) !important;border:none !important;border-top:1px solid rgba(255,220,240,.4) !important}
[data-wk="quotedraft"] *{color:#D8CCEC !important;border-color:#F6B9DC !important}
[data-wk="quoteicon"]{display:none !important}
[data-wk="quoteclear"]{color:#fff !important}
[data-wk="quote"]{background:rgba(255,255,255,.08) !important;color:#D8CCEC !important;border:none !important;border-left:2px solid #F6B9DC !important;border-radius:0 8px 8px 0 !important;padding:3px 10px !important;opacity:1 !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid currentColor !important;padding-left:8px !important;opacity:.7 !important}

/* 打电话那一屏：同一片紫夜和粉云海；他的头像是那只巨眼；挂断＝一颗粉云 */
[data-wk="call"][data-video="0"]{background:url("data:image/svg+xml;base64,") 0 0/220px 260px,radial-gradient(ellipse at 50% 108%,#FFB8DE 0 18%,rgba(246,185,220,.55) 30%,transparent 55%),linear-gradient(180deg,#2B1F55 0%,#4A3285 45%,#8A4FA8) !important}
[data-wk="call"][data-video="0"] [data-wk="calltitle"]{color:#fff !important;letter-spacing:.25em !important}
[data-wk="call"][data-video="0"] [data-wk="callhead"] > div:not([data-wk]){color:#D8CCEC !important}
[data-wk="call"][data-video="0"] > button:first-child{background:rgba(255,255,255,.12) !important;box-shadow:0 0 0 1px rgba(255,220,240,.6) !important}
[data-wk="call"][data-video="0"] > button:first-child svg{stroke:#fff !important}
[data-wk="callbtns"] button > span:first-child{background:rgba(255,255,255,.12) !important;border-radius:50% !important;box-shadow:0 0 0 1px rgba(255,220,240,.6) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#fff !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:radial-gradient(ellipse at 50% 35%,#FFFAFD,#FFE8F4 70%,#F2C6E0) !important;box-shadow:0 0 18px 4px rgba(255,190,230,.6) !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#5A3A70 !important}
[data-wk="call"][data-video="0"] [data-wk="callbtns"] button > span:last-child{color:#D8CCEC !important}
[data-wk="callbubble"]{background:#FFE8F4 !important;color:#5A3A70 !important;border:none !important;border-radius:14px !important;box-shadow:0 0 14px rgba(255,190,225,.45) !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:#5A5288 !important;color:#fff !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
[data-wk="callbubble"][data-kind="typing"] [data-wk="typingdot"]{background:#5A3A70 !important}
[data-wk="callact"]{color:#F6B9DC !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:0 0 0 4px #fff,0 0 0 9px rgba(255,138,216,.55),0 0 0 14px rgba(106,240,192,.3),0 0 40px 14px rgba(255,190,230,.5) !important;animation:ceGlow 3s ease-in-out infinite !important}
